<?php

declare(strict_types=1);

namespace App\Shared\Capabilities\Console;

use App\Shared\Capabilities\Capability;
use App\Shared\Ids\IdPrefix;
use Illuminate\Console\Command;

/**
 * Writes the TypeScript types that mirror PHP enums: capability names and branded public IDs. CI runs it with --check so
 * the generated files never drift from the enums.
 */
final class GenerateTypesCommand extends Command
{
    protected $signature = 'bitflag:types {--check : Fail if the generated files are out of date instead of writing them}';

    protected $description = 'Generate resources/js/types/capabilities.ts and ids.ts from the PHP enums';

    public function handle(): int
    {
        $files = [
            resource_path('js/types/capabilities.ts') => $this->capabilities(),
            resource_path('js/types/ids.ts') => $this->ids(),
        ];

        $stale = [];

        foreach ($files as $path => $contents) {
            if ($this->option('check')) {
                if (! is_file($path) || file_get_contents($path) !== $contents) {
                    $stale[] = $path;
                }

                continue;
            }

            file_put_contents($path, $contents);
            $this->components->info('Wrote '.str_replace(base_path().'/', '', $path));
        }

        if ($stale !== []) {
            $this->components->error('Out of date: '.implode(', ', array_map(fn (string $p): string => str_replace(base_path().'/', '', $p), $stale)).'. Run `php artisan bitflag:types` and commit the result.');

            return self::FAILURE;
        }

        return self::SUCCESS;
    }

    private function capabilities(): string
    {
        $names = array_map(static fn (Capability $c): string => "  '{$c->value}',", Capability::cases());

        return "// Generated by `php artisan bitflag:types` from App\\Shared\\Capabilities\\Capability. Do not edit.\n\n"
            ."export const CAPABILITY_NAMES = [\n".implode("\n", $names)."\n] as const;\n\n"
            ."export type CapabilityName = (typeof CAPABILITY_NAMES)[number];\n";
    }

    private function ids(): string
    {
        $types = [];
        $prefixes = [];

        foreach (IdPrefix::cases() as $prefix) {
            $type = $prefix->name.'Id';
            $types[] = "/** A public ID starting with `{$prefix->value}`. */\nexport type {$type} = `{$prefix->value}\${string}` & { readonly __brand: '{$type}' };";
            $prefixes[] = "  {$prefix->name}: '{$prefix->value}',";
        }

        return "// Generated by `php artisan bitflag:types` from App\\Shared\\Ids\\IdPrefix. Do not edit.\n\n"
            .implode("\n\n", $types)."\n\n"
            ."export const ID_PREFIXES = {\n".implode("\n", $prefixes)."\n} as const;\n";
    }
}
